    "dataClasses": ["pii"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Any user can make themselves an admin by adding a role field to the update request",
      "scenario": "A normal authenticated user calls the display-name update endpoint but adds \"role\":\"admin\" to the JSON body. Because the handler copies every field onto the user record, the attacker's role is overwritten and they gain administrative access to the whole application, including any admin-only data and actions. No special tooling is needed, only an HTTP client.",
      "component": "PATCH /users/{id} update handler",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        {
          "quote": "copies every field onto the user record, including fields like role and accountStatus"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-915", "CWE-269"],
      "plainLanguage": "Someone editing their own name could also send \"role: admin\" and the system would believe them.",
      "requirement": {
        "title": "Bind only an explicit allow-list of user-editable fields",
        "given": "an authenticated user sends a PATCH to /users/{id}",
        "when": "the body contains fields outside the allow-list such as role or accountStatus",
        "then": "those fields are ignored (or the request is rejected) and only the permitted profile fields such as display name are written"
      }
    },
    {
      "stride": "Tampering",
      "title": "Account status can be changed through the profile update, re-enabling suspended accounts",
      "scenario": "A suspended, locked or deactivated user sends \"accountStatus\":\"active\" in the profile update body and the field is copied straight onto their record, undoing a moderation or security action. The same field can be set to disabled on another record to lock a colleague out, defeating offboarding and abuse controls.",
      "component": "User record mapper (accountStatus field)",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "PATCH /users/{id} accepts a JSON body and copies every field onto the user record, including fields like role and accountStatus."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-915"],
      "plainLanguage": "A banned user could un-ban themselves just by editing their profile.",
      "requirement": {
        "title": "Account status changes only through the dedicated administrative path",
        "given": "a profile update request that includes accountStatus",
        "when": "the request arrives on the user profile endpoint",
        "then": "the status is not modified and the change is only possible through an admin-authorised status-change operation"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "The user id is taken from the URL, so one user may be able to edit another user's record",
      "scenario": "The endpoint identifies the target by the {id} path parameter rather than the caller's session. If the handler does not compare {id} to the authenticated user, an attacker iterates ids and patches other people's records, combining with the mass assignment above to grant themselves rights through, or take over, any other account.",
      "component": "PATCH /users/{id} authorisation check",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "PATCH /users/{id} accepts a JSON body"
        },
        {
          "quote": "Users call it to update their display name."
        }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-639"],
      "plainLanguage": "Changing the number in the web address could let you edit somebody else's profile.",
      "requirement": {
        "title": "Enforce object-level authorisation on the user update endpoint",
        "given": "an authenticated user calls PATCH /users/{id}",
        "when": "the id does not match the caller's own user id and the caller holds no user-administration permission",
        "then": "the request is rejected with 403 and no field is written"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Identity and login fields can be overwritten through the same body, enabling account takeover",
      "scenario": "Because every submitted field is copied, an attacker can also set identity-bearing fields such as email, username, verification flags or linked identifiers on a record. Changing the email on a record and then using the normal password-reset flow lets the attacker receive the reset mail and take over that account, without ever knowing the password.",
      "component": "User record mapper (identity fields)",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "copies every field onto the user record"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-915"],
      "plainLanguage": "If you can change the email on an account, you can ask for a password reset and own it.",
      "requirement": {
        "title": "Identity fields require verification, not a plain profile write",
        "given": "a profile update containing email, username or a verification flag",
        "when": "the handler processes the body",
        "then": "these fields are excluded from the profile write and any change goes through a re-authenticated, verified change flow"
      }
    }
  ]
}
